\section{Full Proof of Theorem~\ref{thm:bias_identity}}
\label{app:derivation}

\paragraph{Setup.}
Under assumptions (A1)--(A4), the observed CATE in subgroup $s$ at effect-modifier level $z$ is
\begin{equation}
\tau_{\text{obs}}(z, s) = \sum_{z'} M_s[z, z'] \cdot \tau(z'),
\end{equation}
where $M_s[z, z'] = P(Z{=}z' \mid \hat{Z}{=}z, S{=}s)$ is the mixing matrix.
Under (A2)--(A3), $M_s = \bigl[\begin{smallmatrix} 1-\pi_s & \pi_s \\ \pi_s & 1-\pi_s \end{smallmatrix}\bigr]$.

\paragraph{Global correction.}
The pooled mixing matrix is $M_{\text{global}} = \sum_s w_s M_s = \bigl[\begin{smallmatrix} 1-\bar{\pi} & \bar{\pi} \\ \bar{\pi} & 1-\bar{\pi} \end{smallmatrix}\bigr]$, with $\bar{\pi} = \sum_s w_s \pi_s$.

Global correction applies $M_{\text{global}}^{-1}$ to $\tau_{\text{obs}}(\cdot, s)$:
\begin{equation}
\hat{\tau}_{\text{global}}(z, s) = [M_{\text{global}}^{-1} M_s \cdot \boldsymbol{\tau}]_z,
\end{equation}
where $\boldsymbol{\tau} = [\tau(0), \tau(1)]^\top$.

\paragraph{Bias computation.}
The bias is $\hat{\tau}_{\text{global}}(z, s) - \tau(z) = [(M_{\text{global}}^{-1} M_s - I) \boldsymbol{\tau}]_z$.

Direct computation gives:
\begin{align}
M_{\text{global}}^{-1} &= \frac{1}{1 - 2\bar{\pi}} \begin{bmatrix} 1-\bar{\pi} & -\bar{\pi} \\ -\bar{\pi} & 1-\bar{\pi} \end{bmatrix}, \\
M_{\text{global}}^{-1} M_s &= \frac{1}{1-2\bar{\pi}} \begin{bmatrix} (1-\bar{\pi})(1-\pi_s) - \bar{\pi}\pi_s & (1-\bar{\pi})\pi_s - \bar{\pi}(1-\pi_s) \\ -\bar{\pi}(1-\pi_s) + (1-\bar{\pi})\pi_s & -\bar{\pi}\pi_s + (1-\bar{\pi})(1-\pi_s) \end{bmatrix}.
\end{align}

Define $\delta_s = \pi_s - \bar{\pi}$. The $(1,1)$ entry simplifies:
\begin{align}
(1-\bar{\pi})(1-\pi_s) - \bar{\pi}\pi_s &= 1 - \bar{\pi} - \pi_s + 2\bar{\pi}\pi_s \\
&= (1 - 2\bar{\pi}) + (\bar{\pi} - \pi_s) + 2\bar{\pi}\pi_s \\
&= (1 - 2\bar{\pi})(1) - \delta_s(1 - 2\bar{\pi})/(1-2\bar{\pi}).
\end{align}

More directly, substituting $\pi_s = \bar{\pi} + \delta_s$:
\begin{equation}
M_{\text{global}}^{-1} M_s - I = \frac{\delta_s}{1-2\bar{\pi}} \begin{bmatrix} -1 & 1 \\ 1 & -1 \end{bmatrix}.
\end{equation}

To verify: the $(1,1)$ entry of $M_{\text{global}}^{-1} M_s$ is
\begin{align}
&\frac{(1-\bar{\pi})(1-\bar{\pi}-\delta_s) - \bar{\pi}(\bar{\pi}+\delta_s)}{1-2\bar{\pi}} \\
&= \frac{(1-\bar{\pi})^2 - (1-\bar{\pi})\delta_s - \bar{\pi}^2 - \bar{\pi}\delta_s}{1-2\bar{\pi}} \\
&= \frac{1 - 2\bar{\pi} - \delta_s}{1-2\bar{\pi}} = 1 - \frac{\delta_s}{1-2\bar{\pi}}.
\end{align}

Applying $(M_{\text{global}}^{-1} M_s - I)$ to $\boldsymbol{\tau}$:
\begin{align}
\text{bias}(z{=}0, s) &= \frac{\delta_s}{1-2\bar{\pi}}(-\tau(0) + \tau(1)) = +\frac{\delta_s \cdot \Delta\tau}{1-2\bar{\pi}}, \\
\text{bias}(z{=}1, s) &= \frac{\delta_s}{1-2\bar{\pi}}(\tau(0) - \tau(1)) = -\frac{\delta_s \cdot \Delta\tau}{1-2\bar{\pi}},
\end{align}
where $\Delta\tau = \tau(1) - \tau(0)$. \qed

\section{Proof of Corollary~\ref{cor:multiclass}}
\label{app:multiclass}

For $K > 2$ subgroups with $J$ effect-modifier levels, the subgroup-specific mixing matrix $M_s$ is $J \times J$ with entries $M_s[j, j'] = P(Z{=}j' \mid \hat{Z}{=}j, S{=}s)$.
The global mixing matrix is $M_{\text{global}} = \sum_s w_s M_s$.

The bias of global correction in subgroup $s$ at level $z$ is:
\begin{equation}
\text{bias}_{\text{global}}(z, s) = [(M_{\text{global}}^{-1} M_s - I) \boldsymbol{\tau}]_z.
\end{equation}

Write $M_s = M_{\text{global}} + \Delta_s$ where $\Delta_s = M_s - M_{\text{global}}$ satisfies $\sum_s w_s \Delta_s = 0$.
Then $M_{\text{global}}^{-1} M_s = I + M_{\text{global}}^{-1} \Delta_s$, so:
\begin{equation}
\text{bias}_{\text{global}}(z, s) = [M_{\text{global}}^{-1} \Delta_s \cdot \boldsymbol{\tau}]_z.
\end{equation}

For symmetric misclassification with per-class error rates $\pi_{s,j}$ and pooled rates $\bar{\pi}_j$, the entries of $\Delta_s$ have the form $\Delta_s[j,j'] = (\bar{\pi}_j - \pi_{s,j}) \cdot h(j, j')$ for a function $h$ determined by the off-diagonal redistribution pattern.
Expanding the matrix-vector product and collecting terms yields:
\begin{equation}
\text{bias}_{\text{global}}(z, s) = \sum_{j=1}^{J} (\bar{\pi}_j - \pi_{s,j}) \cdot (\tau(j) - \bar{\tau}) \cdot g(\bar{\pi}),
\end{equation}
where $g(\bar{\pi})$ collects the matrix-inversion amplification terms and $\bar{\tau} = \sum_j P(Z{=}j) \tau(j)$.

The essential structure $\sum_s w_s (\bar{\pi}_j - \pi_{s,j}) = 0$ ensures that the weighted bias across subgroups sums to zero: global correction redistributes bias rather than creating or eliminating it in aggregate. \qed

\section{Proof of Theorem~\ref{thm:debiasing_hurts}}
\label{app:debiasing_hurts}

The naive estimator has bias $\tau_{\text{obs}}(z,s) - \tau(z)$.
Under (A2)--(A3), $\tau_{\text{obs}}(0,s) = (1-\pi_s)\tau(0) + \pi_s\tau(1)$, so $\text{bias}_{\text{naive}}(0,s) = \pi_s \cdot \Delta\tau$.

Global correction produces larger absolute bias when $|\text{bias}_{\text{global}}(0,s)| > |\text{bias}_{\text{naive}}(0,s)|$:
\begin{equation}
\frac{|\delta_s| \cdot |\Delta\tau|}{|1-2\bar{\pi}|} > \pi_s \cdot |\Delta\tau|.
\end{equation}
Since $\Delta\tau \neq 0$ (otherwise both biases are zero), dividing through gives:
\begin{equation}
\frac{|\delta_s|}{(1-2\bar{\pi}) \cdot \pi_s} > 1,
\end{equation}
where we use $1-2\bar{\pi} > 0$ from (A4).

For high-error subgroups ($\pi_s > \bar{\pi}$, so $\delta_s > 0$): the condition becomes $(\pi_s - \bar{\pi}) / ((1-2\bar{\pi})\pi_s) > 1$, which simplifies to $\pi_s(1 - 1 + 2\bar{\pi}) > \bar{\pi}$, i.e., $2\bar{\pi}\pi_s > \bar{\pi}$, i.e., $\pi_s > 0.5$.
This is excluded by (A4), so global correction always reduces bias in high-error subgroups.

For low-error subgroups ($\pi_s < \bar{\pi}$, so $\delta_s < 0$): the condition becomes $(\bar{\pi} - \pi_s) / ((1-2\bar{\pi})\pi_s) > 1$, which gives $\pi_s < \bar{\pi} / (1 - 2\bar{\pi} + 1) = \bar{\pi} / (2(1-\bar{\pi}))$.
When $\bar{\pi} = 0.15$, any subgroup with $\pi_s < 0.088$ experiences increased bias from global correction. \qed

\section{Semi-Synthetic Data Generating Process}
\label{app:dgp}

\paragraph{Synthetic DGP (Sections~\ref{sec:bias_mechanism}--\ref{sec:budget}).}
We generate $N = 5000$ observations.
Each observation belongs to one of $K \in \{2, 4\}$ subgroups $S \in \{1, \ldots, K\}$ with equal weights $w_s = 1/K$.
The binary effect modifier $Z \in \{0, 1\}$ is drawn with $P(Z{=}1) = 0.5$.
Treatment assignment is $T \sim \text{Bernoulli}(0.5)$, independent of $Z$ and $S$.

The outcome is generated as:
\begin{equation}
Y = \tau(Z) \cdot T + \varepsilon, \quad \varepsilon \sim \mathcal{N}(0, 1),
\end{equation}
where the CATE function is $\tau(z) = \bar{\tau} + \Delta\tau \cdot (z - 0.5)$ with $\bar{\tau} = 0.5$.
The CATE heterogeneity $\Delta\tau \in \{0, 0.2, 0.5, 1.0\}$ controls the strength of treatment effect variation across levels of $Z$.

Misclassification is symmetric: $\hat{Z} \neq Z$ with probability $\pi_s$ depending on subgroup.
For $K{=}2$: $\pi_1 = \bar{\pi} - \Delta_c/2$, $\pi_2 = \bar{\pi} + \Delta_c/2$, with $\bar{\pi} \in \{0.1, 0.2\}$ and $\Delta_c \in \{0, 0.05, 0.1, 0.15\}$.
For $K{=}4$, extreme regime: $\pi \in \{0.05, 0.10, 0.15, 0.25\}$; moderate regime: $\pi \in \{0.08, 0.12, 0.16, 0.20\}$.

Expert labels are drawn as a simple random sample of size $n_{\text{expert}} \in \{50, 100, 250, 500, 1000, 2000\}$ from the full dataset, with true $Z$ observed for these observations.

\paragraph{Semi-synthetic DGP (Section~\ref{sec:ec_hte_eval}).}
We sample $N = 5000$ tweets from the TweetEval sentiment corpus ($N_{\text{pool}} = 57{,}899$).
Subgroups are defined by crossing \texttt{has\_hashtag} $\times$ \texttt{text\_length\_bin} (short/medium/long), yielding $K = 4$ subgroups with empirical sizes: $S_0 \approx 38\%$, $S_1 \approx 38\%$, $S_2 \approx 12\%$, $S_3 \approx 12\%$.
Misclassification rates in the extreme regime are $\pi_{S_0} = 0.05$, $\pi_{S_1} = 0.10$, $\pi_{S_2} = 0.15$, $\pi_{S_3} = 0.25$, reflecting empirical evidence that hashtag-heavy text degrades LLM classifier accuracy.
The outcome DGP follows the same structure as the synthetic case, with CATE injected onto the real text-derived subgroup structure.

\paragraph{PPCI DGPs (Section~\ref{sec:ppci}).}
Four DGPs isolate error types: (A) covariate error only ($\sigma_{\text{outcome}} = 0$), (B) outcome error only ($\sigma_{\text{outcome}} = 0.5$), (C) both errors ($\sigma_{\text{outcome}} = 0.5$), (D) no error ($\sigma_{\text{outcome}} = 0$).
Outcome-side error is additive Gaussian noise on $Y$.

\section{MCMC Convergence Diagnostics}
\label{app:mcmc}

Table~\ref{tab:mcmc} reports convergence diagnostics for the hierarchical Bayesian confusion matrix estimator across all experimental configurations.
All runs use 4 chains with 4000 iterations (2000 warmup) and a $\text{Gamma}(3, 1)$ hyperprior on the Dirichlet concentration $\alpha_0$.

\begin{table}[h]
\centering
\small
\begin{tabular}{lcc}
\toprule
Diagnostic & Threshold & Achieved \\
\midrule
$\hat{R}$ (max across all params) & $< 1.01$ & $< 1.0034$ \\
ESS (min across all params) & $> 845$ & $> 1618$ \\
Divergent transitions & $= 0$ & $0$ \\
Singularity guard triggers & --- & extreme/$n{=}50$ only \\
\bottomrule
\end{tabular}
\caption{MCMC convergence diagnostics for the hierarchical Bayesian estimator. All configurations satisfy convergence criteria with substantial margin.}
\label{tab:mcmc}
\end{table}

\paragraph{Hyperprior sensitivity.}
Scaling the $\text{Gamma}(3, 1)$ hyperprior by factors of $0.5\times$ to $2\times$ produces $<$1\% RMSE variation for $K{=}2$ and $\sim$4--5\% for $K{=}4$.
Coverage remains invariant across the sensitivity range.
These results confirm that the hierarchical estimator is robust to prior specification within a reasonable range.

\section*{Responsible NLP Research Checklist}

\paragraph{A. Did you describe the limitations of your work?}
Yes. Section ``Limitations'' discusses five specific limitations: expert budget thresholds, RMSE tradeoff at small sample sizes, plug-in standard error approximation, symmetric misclassification assumption, and known subgroup structure requirement.

\paragraph{B. Did you discuss any potential risks of your work?}
Yes. The method corrects bias in treatment effect estimates used for resource allocation decisions. We explicitly discuss conditions under which EC-HTE should \textit{not} be applied (low error heterogeneity, insufficient expert budget), preventing misuse of stratified correction where global correction is more appropriate.

\paragraph{C. Do the abstract and introduction summarize the paper's main claims?}
Yes. The abstract states all five contributions with specific quantitative results. The introduction provides detailed context and a numbered contribution list.

\paragraph{D1. Did you describe the experimental setup, including hyperparameter search?}
Yes. Section~\ref{sec:experiments} specifies all DGP parameters, Monte Carlo configurations, and method variants. Appendix~\ref{app:dgp} provides the complete data generating process specification. The hierarchical Bayesian estimator uses a $\text{Gamma}(3, 1)$ hyperprior with sensitivity analysis (Appendix~\ref{app:mcmc}).

\paragraph{D2. Did you report error bars or statistical significance?}
Yes. All results are averaged over 100 Monte Carlo runs. We report 95\% CI coverage as a primary metric. RMSE captures both bias and variance. We do not use the term ``significant'' without formal testing.

\paragraph{D3. Did you include the number of parameters and computational budget?}
Yes. The MCMC sampler uses 4 chains $\times$ 4000 iterations. Computational cost is modest (offline calibration). The number of estimated parameters scales as $O(K \cdot J^2)$ where $K$ is subgroups and $J$ is effect-modifier levels.

\paragraph{D4. Did you report the number and range of hyperparameters searched?}
Yes. Hyperprior sensitivity analysis covers $0.5\times$ to $2\times$ scaling of the $\text{Gamma}(3,1)$ concentration prior (Appendix~\ref{app:mcmc}). No other hyperparameters are tuned.

\paragraph{E1. Did you use or create scientific artifacts?}
Yes. We use the TweetEval sentiment corpus for semi-synthetic experiments. We will release our experimental code and synthetic data generation scripts upon acceptance.

\paragraph{E2. Did you discuss the license or terms for use and/or distribution of any artifacts?}
The TweetEval corpus is publicly available under its original license. Our code will be released under an open-source license.

\paragraph{E3. Did you discuss if your use of existing artifact(s) was consistent with their intended use?}
Yes. TweetEval is a benchmark for tweet classification. We use it as a source of realistic text features for semi-synthetic CATE experiments, which is consistent with its role as a research benchmark.

\paragraph{F1. Did you include the full text of instructions given to participants?}
Not applicable. No human participants were involved in this study. Expert labels in the semi-synthetic experiments are simulated from known ground truth.

\paragraph{F2. Did you report information about how you recruited participants?}
Not applicable.

\paragraph{F3. Did you discuss if and how consent was obtained?}
Not applicable.

\paragraph{F4. Were the individuals in the dataset informed about the data collection?}
The TweetEval corpus is a pre-existing public dataset. No new data was collected from individuals.

\paragraph{G. Did you discuss whether and how your work could be misused?}
The primary risk is applying EC-HTE when its assumptions are violated (asymmetric misclassification, unknown subgroup structure). We provide a computable diagnostic criterion that guards against inappropriate application and discuss boundary conditions explicitly.

